-- KANTON — seed com o catálogo real extraído do Instagram @usekanton.
-- Rode depois de 0001_schema.sql. Reexecutável: atualiza o que já existe.
-- As fotos ficam em /public/produtos no repositório; envios novos pelo
-- painel vão para o bucket produtos do Storage.

on conflict (slug) do update set nome = excluded.nome, ordem = excluded.ordem;

on conflict (slug) do update set
  nome = excluded.nome, descricao = excluded.descricao, marca = excluded.marca,
  preco = excluded.preco, preco_promocional = excluded.preco_promocional,
  categoria_id = excluded.categoria_id, tamanhos = excluded.tamanhos,
  cores = excluded.cores, destaque = excluded.destaque, ativo = excluded.ativo,
  ordem = excluded.ordem;

-- imagens: refaz a lista de cada peça
delete from produto_imagens where produto_id in (select id from produtos where slug in ('new-balance-9060-branco-e-cinza', 'new-balance-9060-creme-e-cinza', 'new-balance-9060-creme-e-vinho', 'new-balance-9060-marrom-e-creme', 'new-balance-9060-preto', 'new-balance-9060-preto-e-branco', 'new-balance-bege-e-caramelo', 'new-balance-ct302-preto-e-branco', 'adidas-samba-branco-e-preto', 'adidas-campus-creme-e-marrom', 'adidas-azul-e-dourado', 'adidas-rosa-e-bronze', 'louis-vuitton-branco-e-caramelo', 'louis-vuitton-azul-e-branco', 'nike-free-cinza-e-coral', 'nike-free-preto-e-coral', 'puma-suede-preto-e-branco', 'puma-plataforma-preto', 'puma-branco', 'olimpikus-corrida-branco-e-rosa', 'conjunto-de-alfaiataria-off-white', 'conjunto-de-alfaiataria-marrom-escuro', 'conjunto-de-alfaiataria-taupe', 'conjunto-camisa-e-calca-bege', 'conjunto-colete-e-saia-caramelo', 'blusa-de-cetim-bege-manga-bufante', 'body-de-renda-preto-gola-alta', 'body-de-renda-azul-marinho', 'jaqueta-de-couro-caramelo', 'jaqueta-jeans-clara', 'vestido-marrom-manga-longa', 'vestido-plissado-off-white', 'conjunto-camisa-e-saia-marrom', 'legging-alo-preta-cintura-alta', 'legging-alo-rosa', 'legging-alo-cores-sortidas', 'camiseta-nike-dri-fit-preta', 'short-adidas-magenta', 'pijama-de-renda-vermelho', 'camisola-de-cetim-off-white', 'pijama-de-cetim-preto', 'pijama-de-cetim-rosa', 'robe-de-renda-rosa', 'camisa-do-brasil-amarela'));

on conflict (chave) do update set valor = excluded.valor;
